using Xunit;

namespace ST16.CC.Tests;

/// <summary>
/// Golden-assembly tests: the codegen output for small programs is pinned
/// exactly, so any idiom change (operand order, stack tracking, scratch
/// layout) that changes the emitted words is caught immediately.
/// </summary>
public class GoldenTests
{
    [Fact]
    public void MainReturnZero_GoldenAssembly()
    {
        const string src = "int main()\n{\n    return 0;\n}\n";
        string asm = CCCompiler.Compile(src, "g1.c").Asm.TrimEnd('\n');
        Assert.Equal(
"""
; generated by st16cc — do not edit
; L1
CALL main
HALT
main:
; L1
PUSH16 0xE000
LOAD
PUSH 16
SUB
PUSH16 0xE000
STORE
; L3
; L3
PUSH 0
PUSH16 0xE000
LOAD
PUSH 16
ADD
PUSH16 0xE000
STORE
RET
.org 0xE000
sp:
.dw 0xE000
.org 0xE001
.org 0xE001
st16cc_scratch:
.ds 2
""",
            asm);
    }

    [Fact]
    public void PutcharAndTernary_GoldenAssembly()
    {
        const string src =
            "int main()\n" +
            "{\n" +
            "    int x = 6 * 7;\n" +
            "    putchar('x' + x - 42);\n" +
            "    return x == 42 ? 0 : 1;\n" +
            "}\n";
        string asm = CCCompiler.Compile(src, "g2.c").Asm.TrimEnd('\n');
        Assert.Equal(
"""
; generated by st16cc — do not edit
; L1
CALL main
HALT
main:
; L1
PUSH16 0xE000
LOAD
PUSH 17
SUB
PUSH16 0xE000
STORE
; L3
; L3
; L3
PUSH 6
; L3
PUSH 7
MUL
PUSH16 0xE000
LOAD
PUSH 0
ADD
STORE
; L4
; L4
; L4
; L4
; L4
PUSH 120
; L4
PUSH16 0xE000
LOAD
PUSH 0
ADD
LOAD
ADD
; L4
PUSH 42
SUB
DUP
PUSH16 0xF000
STORE
DROP
; L5
; L5
; L5
; L5
PUSH16 0xE000
LOAD
PUSH 0
ADD
LOAD
; L5
PUSH 42
EQ
JNZ bb0
; L5
PUSH 1
JMP bb1
bb0:
; L5
PUSH 0
bb1:
PUSH16 0xE000
LOAD
PUSH 17
ADD
PUSH16 0xE000
STORE
RET
.org 0xE000
sp:
.dw 0xE000
.org 0xE001
.org 0xE001
st16cc_scratch:
.ds 2
""",
            asm);
    }

    [Fact]
    public void GeneratedAssembly_RoundTripsThroughAssembler()
    {
        // Whatever the codegen emits, the assembler must accept it and the
        // result must contain the SP word and the entry stub.
        const string src = "int main()\n{\n    return 7;\n}\n";
        var output = CCCompiler.Compile(src, "g3.c");
        Assert.True(output.Assembly.Success, string.Join("; ", output.Assembly.Diagnostics));
        Assert.Equal((ushort)0xE000, output.Assembly.Words[0xE000]);
        // Entry stub: CALL main (two words: 0x2000, 0x0003) then HALT.
        Assert.Equal((ushort)0x2000, output.Assembly.Words[0]);
        Assert.Equal((ushort)0x0003, output.Assembly.Words[1]);
        Assert.Equal((ushort)0x2400, output.Assembly.Words[2]);
    }
}
